/** The sets and packs the CSSD sterilizes — GET /api/v1/cssd/set-types (who may call: holders of cssd.view or cssd.operate or cssd.manage). */
export function listSetTypes(query?: { active_only?: boolean }): Promise<SetTypeOut[]> {
  return api<SetTypeOut[]>("GET", withQuery(`/cssd/set-types`, query), undefined);
}

/** Add a set or pack — POST /api/v1/cssd/set-types (who may call: holders of cssd.manage). */
export function createSetType(body: SetTypeIn): Promise<SetTypeOut> {
  return api<SetTypeOut>("POST", `/cssd/set-types`, body, { idempotent: true });
}

/** Change or retire a set — PATCH /api/v1/cssd/set-types/{set_type_id} (who may call: holders of cssd.manage). */
export function updateSetType(set_type_id: number, body: SetTypeUpdateIn): Promise<SetTypeOut> {
  return api<SetTypeOut>("PATCH", `/cssd/set-types/${set_type_id}`, body);
}

/** The sterilizers — GET /api/v1/cssd/sterilizers (who may call: holders of cssd.view or cssd.operate or cssd.manage). */
export function listSterilizers(query?: { active_only?: boolean }): Promise<SterilizerOut[]> {
  return api<SterilizerOut[]>("GET", withQuery(`/cssd/sterilizers`, query), undefined);
}

/** Add a sterilizer — POST /api/v1/cssd/sterilizers (who may call: holders of cssd.manage). */
export function createSterilizer(body: SterilizerIn): Promise<SterilizerOut> {
  return api<SterilizerOut>("POST", `/cssd/sterilizers`, body, { idempotent: true });
}

/** Change or retire a sterilizer — PATCH /api/v1/cssd/sterilizers/{sterilizer_id} (who may call: holders of cssd.manage). */
export function updateSterilizer(sterilizer_id: number, body: SterilizerUpdateIn): Promise<SterilizerOut> {
  return api<SterilizerOut>("PATCH", `/cssd/sterilizers/${sterilizer_id}`, body);
}

/** The sterilization cycles — GET /api/v1/cssd/cycles (who may call: holders of cssd.view or cssd.operate or cssd.manage). */
export function listCyclesCssd(query?: { sterilizer_id?: number | null; cycle_type?: "Load" | "BowieDick" | "LeakTest" | "BiologicalTest" | null; status?: "Running" | "Quarantined" | "Released" | "Failed" | "Recalled" | null; date_from?: string | null; date_to?: string | null; limit?: number }): Promise<SterilizationCycleOut[]> {
  return api<SterilizationCycleOut[]>("GET", withQuery(`/cssd/cycles`, query), undefined);
}

/** One cycle — GET /api/v1/cssd/cycles/{cycle_id} (who may call: holders of cssd.view or cssd.operate or cssd.manage). */
export function getCycleCssdCycles(cycle_id: number): Promise<SterilizationCycleDetailOut> {
  return api<SterilizationCycleDetailOut>("GET", `/cssd/cycles/${cycle_id}`, undefined);
}

/** Recall a released load (a breakdown was found) — POST /api/v1/cssd/cycles/{cycle_id}/recall (who may call: holders of cssd.manage). */
export function recall(cycle_id: number, body: LoadRecallIn): Promise<SterilizationCycleDetailOut> {
  return api<SterilizationCycleDetailOut>("POST", `/cssd/cycles/${cycle_id}/recall`, body, { idempotent: true });
}

